    from collections import deque
    queue = deque([(goal_pos[0], goal_pos[1])])
    visited = {(goal_pos[0], goal_pos[1]): 0}

    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != 'X' and (nx, ny) not in visited:
